template:
class Node:
    def __init__(self, val, next=None):
        self.val, self.next = val, next

def reverse(head):
    prev, cur = None, head
    while cur:
        nxt = cur.next            # save the rest before you cut
        cur.next = prev           # flip the arrow
        prev, cur = cur, nxt
    return prev                   # old tail is the new head

def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

print(to_list(reverse(Node(1, Node(2, Node(3))))))  # -> [3, 2, 1]
